//! 语言服务后端: 将内置 WebGAL LSP 桥接到浏览器 WebSocket。
//!
//! 应用启动后调用一次 [`start_server`] 获取端口, 前端通过
//! `ws://127.0.0.1:{port}` 直连。支持连接断开后重连: 每次接入的
//! WebSocket 连接都会获得一个全新的 LSP 服务实例。
//!
//! WebSocket 通过社区实现 [`ws_stream_tungstenite`] 包装为字节流
//! (AsyncRead + AsyncWrite), 直接 `Server::new(reader, writer, socket)` 启动。

use async_tungstenite::accept_async;
use tauri::State;
use tokio::{net::TcpListener, sync::Mutex, task::JoinHandle};
use tokio_util::compat::TokioAsyncReadCompatExt;
use tower_lsp::{LspService, Server};
use webgal_language_server::server::BackendBuilder;
use ws_stream_tungstenite::WsStream;

#[derive(Debug, Default)]
pub struct LspState {
    pub(crate) server_task: Mutex<Option<JoinHandle<()>>>,
}

/// 启动语言服务后端 WebSocket 服务并返回监听端口。
#[tauri::command]
pub async fn start_server(state: State<'_, LspState>) -> Result<u16, String> {
    if state.server_task.lock().await.is_some() {
        return Err("LSP server already started".into());
    }

    let listener = TcpListener::bind("127.0.0.1:0")
        .await
        .map_err(|e| e.to_string())?;
    let port = listener.local_addr().map_err(|e| e.to_string())?.port();

    let handle = tokio::spawn(async move {
        loop {
            let (stream, _addr) = match listener.accept().await {
                Ok(conn) => conn,
                Err(e) => {
                    eprintln!("LSP: 接受连接失败: {e}");
                    break;
                }
            };

            let ws_stream = match accept_async(stream.compat()).await {
                Ok(ws) => ws,
                Err(e) => {
                    eprintln!("LSP: WebSocket 握手失败: {e}");
                    continue;
                }
            };

            // 每个连接一个独立的 LSP 服务实例
            let builder = BackendBuilder::default();
            let (service, socket) = LspService::new(move |client| builder.build(client));

            let (reader, writer) = tokio::io::split(WsStream::new(ws_stream));
            Server::new(reader, writer, socket).serve(service).await;
        }
    });

    *state.server_task.lock().await = Some(handle);
    Ok(port)
}
